use anyhow::{ensure, Result};
use risc0_zkvm::{ExecutorEnv, ProveInfo, default_prover};
use symthaea_zkproof_core::{
    BalanceProofInput, BalanceProofOutput, BalanceProofRequestBoundInputV1,
    BalanceProofRequestBoundOutputV1, BalanceProofRequestV1, EvolutionInput, EvolutionOutput,
};

// Re-exported from the methods crate (generated by risc0-build).
// The constant names are derived from the guest binary target name
// ("symthaea-zkproof-guest" → SYMTHAEA_ZKPROOF_GUEST_*).
use symthaea_zkproof_methods::{SYMTHAEA_ZKPROOF_GUEST_ELF, SYMTHAEA_ZKPROOF_GUEST_ID};

// ---------------------------------------------------------------------------
// Consciousness attestation prover (tag = 0)
// ---------------------------------------------------------------------------

pub struct EvolutionaryProver;

impl EvolutionaryProver {
    pub fn prove(input: EvolutionInput) -> Result<ProveInfo> {
        let env = ExecutorEnv::builder()
            .write(&0u8)? // tag = 0
            .write(&input)?
            .build()?;

        let prover = default_prover();
        let prove_info = prover.prove(env, SYMTHAEA_ZKPROOF_GUEST_ELF)?;
        Ok(prove_info)
    }

    pub fn verify(prove_info: &ProveInfo) -> Result<EvolutionOutput> {
        prove_info.receipt.verify(SYMTHAEA_ZKPROOF_GUEST_ID)?;
        let output: EvolutionOutput = prove_info.receipt.journal.decode()?;
        Ok(output)
    }
}

// ---------------------------------------------------------------------------
// Balance sufficiency prover (tag = 1)
// ---------------------------------------------------------------------------

/// Proves that a balance is sufficient (>= required minimum) without
/// revealing the actual balance.
///
/// The proof commits to:
/// - `sufficient: bool` (PUBLIC)
/// - `required_minimum: u64` (PUBLIC)
/// - `nonce: u64` (PUBLIC)
///
/// The actual balance is PRIVATE — included in the proof computation
/// but never revealed.
pub struct BalanceProver;

impl BalanceProver {
    /// Generate a ZK proof that `balance >= required_minimum`.
    ///
    /// Returns the proof receipt containing the public outputs.
    /// The actual balance is never revealed.
    pub fn prove(balance: u64, required_minimum: u64, nonce: u64) -> Result<ProveInfo> {
        let env = ExecutorEnv::builder()
            .write(&1u8)? // tag = 1 (balance proof)
            .write(&BalanceProofInput {
                balance,
                required_minimum,
                nonce,
            })?
            .build()?;

        let prover = default_prover();
        let prove_info = prover.prove(env, SYMTHAEA_ZKPROOF_GUEST_ELF)?;
        Ok(prove_info)
    }

    /// Verify a balance proof receipt and decode the public output.
    pub fn verify(prove_info: &ProveInfo) -> Result<BalanceProofOutput> {
        prove_info.receipt.verify(SYMTHAEA_ZKPROOF_GUEST_ID)?;
        let output: BalanceProofOutput = prove_info.receipt.journal.decode()?;
        Ok(output)
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_balance_proof_sufficient() {
        let prove_info = BalanceProver::prove(1000, 500, 42).unwrap();
        let output = BalanceProver::verify(&prove_info).unwrap();
        assert!(output.sufficient);
        assert_eq!(output.required_minimum, 500);
        assert_eq!(output.nonce, 42);
    }

    #[test]
    fn test_balance_proof_insufficient() {
        let prove_info = BalanceProver::prove(100, 500, 43).unwrap();
        let output = BalanceProver::verify(&prove_info).unwrap();
        assert!(!output.sufficient);
    }

    #[test]
    fn test_balance_proof_exact() {
        let prove_info = BalanceProver::prove(500, 500, 44).unwrap();
        let output = BalanceProver::verify(&prove_info).unwrap();
        assert!(output.sufficient);
    }

    #[test]
    fn test_balance_proof_zero_balance() {
        let prove_info = BalanceProver::prove(0, 0, 99).unwrap();
        let output = BalanceProver::verify(&prove_info).unwrap();
        assert!(output.sufficient);
        assert_eq!(output.required_minimum, 0);
    }

    #[test]
    fn test_balance_proof_max_values() {
        let prove_info = BalanceProver::prove(u64::MAX, u64::MAX, u64::MAX).unwrap();
        let output = BalanceProver::verify(&prove_info).unwrap();
        assert!(output.sufficient);
    }

    #[test]
    fn test_consciousness_attestation_still_works() {
        let input = EvolutionInput {
            episodes: vec![vec![0.0, 1.0]],
            tau_scale: 2.0,
            threshold: 0.5,
        };
        let prove_info = EvolutionaryProver::prove(input).unwrap();
        let output = EvolutionaryProver::verify(&prove_info).unwrap();
        assert!((output.average_phi - 1.0).abs() < 1e-6);
        assert_eq!(output.episode_count, 1);
    }
}


// ---------------------------------------------------------------------------
// Request-bound balance proof (tag = 2)
// ---------------------------------------------------------------------------

/// Proves the balance threshold for one exact, externally formed request.
///
/// This API binds the request context into the RISC Zero journal and checks
/// that journal against the exact expected request during verification.
///
/// Important limits:
/// - source/issuer digests are references, not issuer-signature verification;
/// - the guest does not prove that the balance opens the referenced source;
/// - the challenge must be issued and consumed by an external verifier owner;
/// - issuer authority, credential status, policy applicability and action
///   authorization remain external qualification steps.
pub struct BalanceProofRequestBoundProverV1;

impl BalanceProofRequestBoundProverV1 {
    /// Generate a proof bound to the supplied request context.
    pub fn prove(balance: u64, request: BalanceProofRequestV1) -> Result<ProveInfo> {
        request
            .validate()
            .map_err(|error| anyhow::anyhow!("invalid balance proof request: {error}"))?;

        let input = BalanceProofRequestBoundInputV1 { balance, request };
        let env = ExecutorEnv::builder()
            .write(&2u8)? // tag = 2 (request-bound balance proof v1)
            .write(&input)?
            .build()?;

        let prover = default_prover();
        let prove_info = prover.prove(env, SYMTHAEA_ZKPROOF_GUEST_ELF)?;
        Ok(prove_info)
    }

    /// Verify a receipt against the exact request expected by the verifier.
    ///
    /// An otherwise valid receipt for a different audience, verifier,
    /// purpose, source reference, policy, challenge or threshold is rejected.
    /// A valid output with sufficient == false is returned as a valid proof
    /// of insufficiency; application policy decides what that means.
    pub fn verify_for_request(
        prove_info: &ProveInfo,
        expected_request: &BalanceProofRequestV1,
    ) -> Result<BalanceProofRequestBoundOutputV1> {
        expected_request
            .validate()
            .map_err(|error| anyhow::anyhow!("invalid expected balance proof request: {error}"))?;

        prove_info.receipt.verify(SYMTHAEA_ZKPROOF_GUEST_ID)?;
        let output: BalanceProofRequestBoundOutputV1 = prove_info.receipt.journal.decode()?;
        ensure!(
            output.matches_request(expected_request),
            "balance proof receipt does not match the expected request context"
        );
        Ok(output)
    }
}

#[cfg(test)]
mod request_bound_tests {
    use super::*;

    fn sample_request() -> BalanceProofRequestV1 {
        BalanceProofRequestV1 {
            request_id: [1; 16],
            source_statement_reference_digest: [2; 32],
            issuer_key_reference_digest: [3; 32],
            audience_digest: [4; 32],
            verifier_digest: [5; 32],
            purpose_digest: [6; 32],
            policy_digest: [7; 32],
            verifier_challenge: [8; 32],
            required_minimum: 500,
        }
    }

    #[test]
    fn request_bound_receipt_verifies_for_exact_request() {
        let request = sample_request();
        let prove_info =
            BalanceProofRequestBoundProverV1::prove(1_000, request.clone()).unwrap();

        let output =
            BalanceProofRequestBoundProverV1::verify_for_request(&prove_info, &request).unwrap();

        assert!(output.sufficient);
        assert_eq!(output.required_minimum, request.required_minimum);
        assert_eq!(output.request_digest, request.canonical_digest());
    }

    #[test]
    fn request_bound_receipt_rejects_audience_substitution() {
        let request = sample_request();
        let prove_info =
            BalanceProofRequestBoundProverV1::prove(1_000, request.clone()).unwrap();

        let mut wrong_request = request;
        wrong_request.audience_digest[0] ^= 1;

        assert!(
            BalanceProofRequestBoundProverV1::verify_for_request(&prove_info, &wrong_request)
                .is_err()
        );
    }

    #[test]
    fn request_bound_receipt_rejects_threshold_substitution() {
        let request = sample_request();
        let prove_info =
            BalanceProofRequestBoundProverV1::prove(1_000, request.clone()).unwrap();

        let mut wrong_request = request;
        wrong_request.required_minimum += 1;

        assert!(
            BalanceProofRequestBoundProverV1::verify_for_request(&prove_info, &wrong_request)
                .is_err()
        );
    }

    #[test]
    fn request_bound_receipt_can_prove_insufficiency() {
        let request = sample_request();
        let prove_info = BalanceProofRequestBoundProverV1::prove(100, request.clone()).unwrap();
        let output =
            BalanceProofRequestBoundProverV1::verify_for_request(&prove_info, &request).unwrap();

        assert!(!output.sufficient);
    }
}
